void document.addEventListener("DOMContentLoaded",()=>{function e(e){return e.toFixed(2)+" грн"}const t=document.getElementById("fop-form"),n=document.getElementById("fop-result"),o=document.getElementById("period");t.addEventListener("submit",t=>{t.preventDefault();const r=document.getElementById("group").value,s=parseFloat(document.getElementById("income").value),a=o.value;if(isNaN(s)||s<0)return n.innerHTML='<p style="color:red;">Будь ласка, введіть коректний дохід.</p>',void 0;const{singleTax:c,esv:i,military:l,total:d}=function(e,t,n){let o=0,r=0,s=0;if("monthly"===n)switch(e){case"1":o=292,r=1760,s=800;break;case"2":o=1600,r=1760,s=800;break;case"3":o=.05*t,r=1760,s=.01*t;break;case"3-vat":o=.03*t,r=1760,s=.01*t}else switch(e){case"1":o=876,r=5280,s=2400;break;case"2":o=4800,r=5280,s=2400;break;case"3":o=.05*t,r=5280,s=.01*t;break;case"3-vat":o=.03*t,r=5280,s=.01*t}return{singleTax:o,esv:r,military:s,total:o+r+s}}(r,s,a),m="monthly"===a?"за місяць":"за квартал";n.innerHTML=`\n        <p><strong>Єдиний податок ${m}:</strong> ${e(c)}</p>\n        <p><strong>ЄСВ ${m}:</strong> ${e(i)}</p>\n        <p><strong>Військовий збір ${m}:</strong> ${e(l)}</p>\n        <hr>\n        <p><strong>Загалом ${m}:</strong> ${e(d)}</p>\n      `})});